JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0050', 'Logical Reasoning', 'Patterns and sequences', 'Letter and number series', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
A1, C3, E5, G7, ?', '["H8", "I8", "I9", "J9"]', 2, 'The letters skip one each time and the number is the letter''s position: I is the 9th letter.', '{"0": "H is only one step after G.", "1": "I is the 9th letter, so the number must be 9.", "3": "J is the 10th letter."}'),
  ('LR-0051', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
ACE, BDF, CEG, ?', '["DEF", "DGH", "EFG", "DFH"]', 3, 'Each letter of the group moves forward by one: C→D, E→F, G→H.', '{"0": "Inside each group, letters skip one (D, F, H), not run in a row.", "1": "The middle letter should be F.", "2": "The first letter should be D."}'),
  ('LR-0052', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
J, F, M, A, M, J, J, ?', '["A", "S", "O", "J"]', 0, 'These are the first letters of the months: January, February, March, April, May, June, July; next is August.', '{"1": "S (September) comes after August.", "2": "O (October) comes later.", "3": "There is no third month starting with J after July."}'),
  ('LR-0053', 'Logical Reasoning', 'Patterns and sequences', 'Coding', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In a code, CAT is written as DBU. How is COG written in the same code?', '["EPH", "DPH", "DOH", "CNF"]', 1, 'Each letter moves one place forward: C→D, A→B, T→U, so C→D, O→P, G→H gives DPH.', '{"0": "The first letter of COG moves to D, not E.", "2": "O must move to P.", "3": "Moving backwards gives CNF; the code moves forwards."}'),
  ('LR-0054', 'Logical Reasoning', 'Patterns and sequences', 'Coding', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In a code, ROSE is written as TQUG. How is LILY written in the same code?', '["NKNZ", "MJMZ", "NKNA", "NKNB"]', 2, 'Each letter moves two places forward (R→T, O→Q, S→U, E→G). So L→N, I→K, L→N, and Y→A (wrapping round after Z).', '{"0": "Y + 2 wraps round to A, not Z.", "1": "This moves each letter only one place.", "3": "Y + 2 is A, not B."}'),
  ('LR-0055', 'Logical Reasoning', 'Patterns and sequences', 'Symbol series', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
△ △ ○ △ △ ○ △ △ ?', '["△", "□", "◇", "○"]', 3, 'The pattern △ △ ○ repeats, so after two triangles comes a circle.', '{"0": "A third triangle breaks the repeat.", "1": "A square never appears in the pattern.", "2": "A diamond never appears in the pattern."}'),
  ('LR-0056', 'Logical Reasoning', 'Patterns and sequences', 'Symbol series', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What are the next two symbols?
+ − × ÷ + − × ÷ + − ? ?', '["× ÷", "÷ ×", "+ −", "− +"]', 0, 'The block + − × ÷ repeats. After ''+ −'' comes ''× ÷''.', '{"1": "The order within the block is × then ÷.", "2": "+ − has just appeared; × ÷ comes next.", "3": "This order does not occur in the block."}'),
  ('LR-0057', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'All surgeons are doctors. All doctors are graduates.
Which conclusion must be true?', '["All graduates are surgeons", "All surgeons are graduates", "Some graduates are not doctors", "No surgeon is a graduate"]', 1, 'If every surgeon is a doctor and every doctor is a graduate, every surgeon is a graduate.', '{"0": "The statements do not say every graduate is a surgeon.", "2": "This may or may not be true; it does not follow.", "3": "This contradicts the statements."}'),
  ('LR-0058', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'All roses are flowers. Some flowers fade quickly.
Which conclusion must be true?', '["Some roses fade quickly", "All roses fade quickly", "No rose fades quickly", "None of these necessarily follows"]', 3, 'The flowers that fade quickly may or may not include any roses, so no conclusion about roses follows.', '{"0": "The quickly fading flowers might all be other flowers.", "1": "Nothing says all flowers fade quickly.", "2": "Nothing rules out roses fading quickly."}'),
  ('LR-0059', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'No cats are dogs. All puppies are dogs.
Which conclusion must be true?', '["Some puppies are cats", "All dogs are puppies", "No puppies are cats", "Some cats are puppies"]', 2, 'Every puppy is a dog, and no dog is a cat, so no puppy can be a cat.', '{"0": "This contradicts the statements.", "1": "The statements do not say every dog is a puppy.", "3": "This contradicts the statements."}'),
  ('LR-0060', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Some doctors are teachers. All teachers are graduates.
Which conclusion must be true?', '["All doctors are graduates", "All graduates are teachers", "No doctor is a graduate", "Some doctors are graduates"]', 3, 'The doctors who are teachers must be graduates, so at least some doctors are graduates.', '{"0": "Only the doctors who are teachers are known to be graduates.", "1": "The statements do not say this.", "2": "This contradicts the statements."}'),
  ('LR-0061', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'All P are Q. No Q is R.
Which conclusion must be true?', '["No P is R", "Some P are R", "All R are P", "All Q are P"]', 0, 'Every P is inside Q, and nothing in Q is R, so no P can be R.', '{"1": "This contradicts the statements.", "2": "This contradicts the statements.", "3": "The statements do not say every Q is a P."}'),
  ('LR-0062', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Some A are B. Some B are C.
Which conclusion must be true?', '["Some A are C", "All A are C", "No A is C", "None of these necessarily follows"]', 3, 'The B''s that are A and the B''s that are C may be completely different B''s, so nothing follows about A and C.', '{"0": "The overlap between A and C is possible but not certain.", "1": "Nothing supports ''all''.", "2": "Nothing rules out some A being C."}'),
  ('LR-0063', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'All mammals breathe air. Whales are mammals.
Which conclusion must be true?', '["Whales are fish", "Whales breathe air", "All animals that breathe air are whales", "Some mammals are not whales, so they do not breathe air"]', 1, 'Whales belong to the group ''mammals'', and everything in that group breathes air.', '{"0": "This contradicts the statement that whales are mammals.", "2": "The statements do not say this.", "3": "All mammals breathe air, whales or not."}'),
  ('LR-0064', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Only doctors can prescribe this medicine. Rehan prescribed this medicine.
Which conclusion must be true?', '["Rehan is a pharmacist", "Every doctor prescribes this medicine", "Rehan is a doctor", "Rehan is not a doctor"]', 2, '''Only doctors can'' means anyone who prescribes it must be a doctor.', '{"0": "Only doctors can prescribe it.", "1": "''Only doctors can'' does not mean all doctors do.", "3": "This contradicts the statements."}'),
  ('LR-0065', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'If it rains, the match is cancelled. The match was not cancelled.
Which conclusion must be true?', '["It rained", "The match was postponed", "It may or may not have rained", "It did not rain"]', 3, 'If rain always leads to cancellation, and there was no cancellation, then there was no rain.', '{"0": "Rain would have cancelled the match.", "1": "The statements say nothing about postponement.", "2": "Rain is ruled out, because it would have cancelled the match."}'),
  ('LR-0066', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'If it rains, the ground gets wet. The ground is wet.
Which conclusion is correct?', '["It rained", "It did not rain", "It may or may not have rained", "The ground will dry"]', 2, 'The ground can be wet for other reasons (a pipe, washing), so rain cannot be concluded. Concluding it rained is the error of affirming the consequent.', '{"0": "Something else might have made the ground wet.", "1": "Rain is possible; it is just not certain.", "3": "The statements say nothing about drying."}'),
  ('LR-0067', 'Logical Reasoning', 'Logical deductions', 'Ordering', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Sara is taller than Hina. Hina is taller than Amna.
Who is the shortest?', '["Amna", "Sara", "Hina", "Cannot be determined"]', 0, 'The order from tallest is Sara, Hina, Amna, so Amna is the shortest.', '{"1": "Sara is the tallest.", "2": "Hina is in the middle.", "3": "The order is fully fixed by the two statements."}'),
  ('LR-0068', 'Logical Reasoning', 'Logical deductions', 'Ordering', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Mona is older than Tariq. Tariq is older than Nida. Nida is older than Omar.
If the first three statements are true, the statement "Omar is older than Mona" is:', '["True", "False", "Uncertain", "Partly true"]', 1, 'The order from oldest is Mona, Tariq, Nida, Omar. Omar is the youngest, so he cannot be older than Mona.', '{"0": "Omar is younger than everyone else.", "2": "The order is fully fixed.", "3": "A statement is either true or false here."}'),
  ('LR-0069', 'Logical Reasoning', 'Logical deductions', 'Ordering', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Kashif scored more than Laila. Mehr scored more than Laila.
If these are true, the statement "Kashif scored more than Mehr" is:', '["True", "False", "Uncertain", "Always true when Laila scores least"]', 2, 'Both scored more than Laila, but nothing compares Kashif with Mehr, so the statement is uncertain.', '{"0": "Kashif and Mehr are never compared.", "1": "Kashif and Mehr are never compared.", "3": "Laila scoring least says nothing about Kashif and Mehr."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0070', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'All the trainees passed the test. Some trainees are left-handed.
If these are true, the statement "Some left-handed people passed the test" is:', '["True", "False", "Uncertain", "True only for trainees who are right-handed"]', 0, 'The left-handed trainees are trainees, and all trainees passed, so some left-handed people passed.', '{"1": "It follows directly from the statements.", "2": "It follows directly from the statements.", "3": "This mixes up the groups; the left-handed trainees passed."}'),
  ('LR-0071', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement: All the seats in the bus were occupied.
Conclusion I: There was no empty seat in the bus.
Conclusion II: Some passengers were standing.
Which conclusion follows?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'If all seats were occupied, none was empty (I). Whether anyone was standing is not stated (II does not follow).', '{"1": "Full seats do not prove that extra passengers were standing.", "2": "II does not follow.", "3": "I follows directly."}'),
  ('LR-0072', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Ali is the brother of Sana. Sana is the daughter of Kamran.
How is Ali related to Kamran?', '["Brother", "Son", "Father", "Nephew"]', 1, 'Ali and Sana are siblings, and Sana is Kamran''s daughter, so Ali is Kamran''s son.', '{"0": "Ali is a generation below Kamran.", "2": "Ali is a generation below Kamran.", "3": "Ali is Kamran''s own child, not his sibling''s child."}'),
  ('LR-0073', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Pointing to a young man, Fatima said, "He is the son of my father''s father''s only son."
How is the young man related to Fatima?', '["Cousin", "Uncle", "Brother", "Nephew"]', 2, 'Her father''s father''s only son is her father himself. Her father''s son is her brother.', '{"0": "A cousin would be the child of her father''s sibling, but her father is the only son.", "1": "An uncle would be a brother of her father.", "3": "A nephew would be her sibling''s son."}'),
  ('LR-0074', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Huma is the daughter of Bilal''s only sister.
How is Bilal related to Huma?', '["Father", "Paternal uncle", "Brother", "Maternal uncle"]', 3, 'Bilal is the brother of Huma''s mother, so he is her maternal uncle.', '{"0": "Huma''s father is her mother''s husband, not her brother.", "1": "A paternal uncle is the father''s brother.", "2": "Bilal is a generation above Huma."}'),
  ('LR-0075', 'Logical Reasoning', 'Logical deductions', 'Coded relations', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'If "P × Q" means P is the brother of Q, and "P ÷ Q" means P is the mother of Q, what does "A ÷ B × C" mean?', '["A is the mother of C", "A is the sister of C", "C is the mother of A", "A is the grandmother of C"]', 0, 'A ÷ B: A is B''s mother. B × C: B is C''s brother. So B and C are siblings and A is the mother of both.', '{"1": "A is a generation above C.", "2": "This reverses the relation.", "3": "A is only one generation above C."}'),
  ('LR-0076', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'In a class, Hamid is 7th from the top and 14th from the bottom.
How many students are in the class?', '["21", "20", "19", "22"]', 1, 'Total = rank from top + rank from bottom − 1 = 7 + 14 − 1 = 20 (Hamid is counted twice otherwise).', '{"0": "21 counts Hamid twice.", "2": "19 subtracts one too many.", "3": "22 adds one too many."}'),
  ('LR-0077', 'Logical Reasoning', 'Logical problems', 'Seating arrangement', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Five friends, A, B, C, D and E, sit in a row facing north. C sits in the middle. A sits immediately to the left of C. E sits at the right end. B does not sit next to E.
Who sits at the left end?', '["D", "A", "B", "E"]', 2, 'C is 3rd, A is 2nd and E is 5th. B and D take places 1 and 4; B cannot be 4th (next to E), so B is 1st. Order: B, A, C, D, E.', '{"0": "D is 4th, next to E.", "1": "A is 2nd.", "3": "E is at the right end."}'),
  ('LR-0078', 'Logical Reasoning', 'Logical problems', 'Seating arrangement', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Five friends, A, B, C, D and E, sit in a row facing north. C sits in the middle. A sits immediately to the left of C. E sits at the right end. B does not sit next to E.
Who sits between C and E?', '["B", "A", "Nobody", "D"]', 3, 'The order is B, A, C, D, E, so D sits between C and E.', '{"0": "B is at the left end.", "1": "A is to the left of C.", "2": "There is one seat between C (3rd) and E (5th)."}'),
  ('LR-0079', 'Logical Reasoning', 'Logical problems', 'Age problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Sara is twice as old as Ali. In 5 years, the sum of their ages will be 40.
How old is Ali now?', '["10", "15", "12", "20"]', 0, 'Let Ali be x and Sara 2x. In 5 years: (x + 5) + (2x + 5) = 40, so 3x = 30 and x = 10.', '{"1": "15 would give 20 + 35 = 55 in five years.", "2": "12 would give 17 + 29 = 46.", "3": "20 is Sara''s age, not Ali''s."}'),
  ('LR-0080', 'Logical Reasoning', 'Logical problems', 'Age problems', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'A father is 30 years older than his son. In 10 years, the father will be twice as old as his son.
How old is the son now?', '["10", "20", "15", "30"]', 1, 'Let the son be x. Then x + 40 = 2(x + 10), so x = 20. (Check: 20 and 50 now; 30 and 60 in ten years.)', '{"0": "With 10, the ages would be 20 and 50 in ten years, not double.", "2": "With 15, they would be 25 and 55.", "3": "30 is the age gap, not the son''s age."}'),
  ('LR-0081', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Today is Wednesday. What day of the week will it be 100 days from today?', '["Thursday", "Saturday", "Friday", "Wednesday"]', 2, '100 = 14 × 7 + 2, so after 14 full weeks it is Wednesday again, and 2 more days gives Friday.', '{"0": "Thursday is only 1 day on.", "1": "Saturday is 3 days on.", "3": "Wednesday would need a multiple of 7 days."}'),
  ('LR-0082', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'If the day before yesterday was Monday, what day will the day after tomorrow be?', '["Thursday", "Saturday", "Wednesday", "Friday"]', 3, 'The day before yesterday was Monday, so today is Wednesday. The day after tomorrow is Friday.', '{"0": "Thursday is tomorrow.", "1": "Saturday is three days on.", "2": "Wednesday is today."}'),
  ('LR-0083', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In a year that is not a leap year, 1 January is a Monday. What day is 1 March?', '["Thursday", "Wednesday", "Friday", "Monday"]', 0, 'From 1 January to 1 March is 31 + 28 = 59 days. 59 = 8 × 7 + 3, so it is 3 days after Monday: Thursday.', '{"1": "This is 2 days on; the leftover is 3.", "2": "This is 4 days on.", "3": "This would need a multiple of 7 days."}'),
  ('LR-0084', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Six students meet and each shakes hands once with every other student. How many handshakes take place?', '["30", "15", "36", "12"]', 1, 'Each pair shakes hands once: 6 × 5 ÷ 2 = 15.', '{"0": "30 counts every handshake twice.", "2": "36 is 6 × 6, counting students shaking their own hands.", "3": "12 is 6 × 2."}'),
  ('LR-0085', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'A drawer has 10 black socks and 10 white socks, all mixed up. In the dark, what is the smallest number of socks you must take out to be sure of a matching pair?', '["2", "4", "3", "20"]', 2, 'With only two colours, any 3 socks must include two of the same colour.', '{"0": "Two socks could be one black and one white.", "1": "4 is more than needed; 3 socks already guarantee a pair.", "3": "20 is every sock."}'),
  ('LR-0086', 'Logical Reasoning', 'Logical problems', 'Truth and lies', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'A vase was broken. Exactly one of three cousins is lying.
Asad: "Bilal broke the vase."
Bilal: "I did not break it."
Kamil: "Bilal broke the vase."
Who broke the vase?', '["Asad", "Kamil", "Cannot be determined", "Bilal"]', 3, 'If Bilal were telling the truth, Asad and Kamil would both be lying, which makes two liars. So Bilal is the liar and he broke the vase.', '{"0": "Asad and Kamil both name Bilal and they are not lying.", "1": "Asad and Kamil both name Bilal and they are not lying.", "2": "Only one arrangement leaves exactly one liar."}'),
  ('LR-0087', 'Logical Reasoning', 'Logical problems', 'Ordering puzzles', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In a race of five runners, T finished first. P finished before Q but after R. S finished after Q.
Who finished third?', '["P", "R", "Q", "S"]', 0, 'T is first. R, P, Q and S must then be in that order: T, R, P, Q, S. So P is third.', '{"1": "R is second.", "2": "Q is fourth.", "3": "S is fifth."}'),
  ('LR-0088', 'Logical Reasoning', 'Logical problems', 'Code language', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'In a code language:
"red apple sweet" is written "pa ki lo"
"sweet green tea" is written "lo mu se"
"apple tea" is written "ki se"
What is the code for "red"?', '["ki", "pa", "lo", "se"]', 1, '''Apple'' appears in lines 1 and 3, whose common code is ''ki''. ''Sweet'' appears in lines 1 and 2, whose common code is ''lo''. The remaining code in line 1, ''pa'', is ''red''.', '{"0": "''ki'' is the code for ''apple''.", "2": "''lo'' is the code for ''sweet''.", "3": "''se'' is the code for ''tea''."}'),
  ('LR-0089', 'Logical Reasoning', 'Logical problems', 'Ordering puzzles', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Five books are stacked in a pile. Logical Reasoning is at the top and Biology is at the bottom. English is directly below Physics. Physics is somewhere above Chemistry.
Which book is exactly in the middle of the pile?', '["Physics", "Chemistry", "English", "Biology"]', 2, 'Places 2, 3 and 4 hold Physics, English and Chemistry. English must be directly below Physics and Chemistry below Physics, so the order is LR, Physics, English, Chemistry, Biology. English is 3rd.', '{"0": "Physics is 2nd.", "1": "Chemistry is 4th.", "3": "Biology is at the bottom."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0090', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Ali walks 4 km north, then turns right and walks 3 km.
How far is he from his starting point?', '["7 km", "1 km", "12 km", "5 km"]', 3, 'His path makes a right angle, so the straight-line distance is √(4² + 3²) = √25 = 5 km.', '{"0": "7 km is the distance walked, not the distance from the start.", "1": "1 km is 4 − 3.", "2": "12 km is 4 × 3."}'),
  ('LR-0091', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Facing north, you turn 90° clockwise, then 180°, then 90° anticlockwise.
Which direction are you facing now?', '["South", "North", "East", "West"]', 0, 'North → 90° clockwise = east → 180° = west → 90° anticlockwise = south.', '{"1": "You would face north only if the turns cancelled out, but they total 180°.", "2": "East is where you face after the first turn.", "3": "West is where you face after the second turn."}'),
  ('LR-0092', 'Logical Reasoning', 'Logical problems', 'Sets and groups', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In a group of 40 students, 25 study Biology, 20 study Chemistry and 10 study both.
How many study neither subject?', '["0", "5", "15", "10"]', 1, 'Students studying at least one subject = 25 + 20 − 10 = 35, so 40 − 35 = 5 study neither.', '{"0": "0 forgets that the 10 counted twice must be subtracted.", "2": "15 is 25 − 10, those who study only Biology.", "3": "10 is the number who study both."}'),
  ('LR-0093', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'There are 9 identical-looking coins, and one is slightly heavier. Using a two-pan balance, what is the smallest number of weighings that is certain to find the heavy coin?', '["3", "4", "2", "1"]', 2, 'Weigh 3 against 3. The heavier pan holds the coin; if they balance, it is in the other 3. Then weigh 1 against 1 from that group in the same way.', '{"0": "Splitting into groups of three needs only 2 weighings.", "1": "Splitting into groups of three needs only 2 weighings.", "3": "One weighing narrows it to 3 coins, not 1."}'),
  ('LR-0094', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'A pharmacy had 24 strips of a medicine. All but 7 were sold.
How many strips are left?', '["17", "24", "31", "7"]', 3, '''All but 7 were sold'' means every strip except 7 was sold, so 7 are left.', '{"0": "17 is the number sold.", "1": "24 is the starting number.", "2": "31 adds instead of taking away."}'),
  ('LR-0095', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'What is the angle between the hour hand and the minute hand of a clock at exactly 3:00?', '["90°", "45°", "180°", "120°"]', 0, 'Each hour mark is 30° apart. At 3:00 the hands are 3 marks apart: 3 × 30° = 90°.', '{"1": "45° is only 1.5 marks apart.", "2": "180° is at 6:00.", "3": "120° is at 4:00."}'),
  ('LR-0096', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Many patients in a district hospital have developed dengue after a week of heavy rain.
Course of action I: The health department should start a drive to remove mosquito breeding sites in the area.
Course of action II: The hospital should be shut down.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Removing breeding sites tackles the cause of the outbreak. Closing the hospital would deny care to the patients who need it.', '{"1": "Closing the hospital would make things worse.", "2": "II does not follow.", "3": "I is a sensible, practical step."}'),
  ('LR-0097', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A large number of students in one school failed mathematics, while their results in other subjects were good.
Course of action I: The school should review how mathematics is being taught.
Course of action II: All the students should be expelled.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'A problem limited to one subject points to how that subject is taught. Expelling everyone is extreme and does not solve it.', '{"1": "Expelling all students is extreme.", "2": "II does not follow.", "3": "I is a reasonable step."}'),
  ('LR-0098', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Several guests fell ill with food poisoning after eating at a wedding dinner served by a caterer.
Course of action I: Food safety officials should inspect the caterer''s kitchen.
Course of action II: Those who fell ill should be given medical treatment promptly.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Treating the sick deals with the immediate problem, and inspecting the kitchen deals with the cause. Both are reasonable.', '{"0": "II is also needed: sick guests need treatment.", "1": "I is also needed: the cause should be found.", "3": "Both are reasonable steps."}'),
  ('LR-0099', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: The traffic signal at a busy crossing has stopped working.
Course of action I: Traffic police should be posted to control traffic until it is repaired.
Course of action II: The authorities should get the signal repaired quickly.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Police control the immediate danger, and repair fixes the cause. Both follow.', '{"0": "II is also needed to fix the problem.", "1": "I is also needed until the repair is done.", "3": "Both are sensible."}'),
  ('LR-0100', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A student has been absent from college for two weeks without informing anyone.
Course of action I: The college should contact the student''s parents.
Course of action II: The student should be expelled immediately.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Finding out the reason comes first; expelling without knowing why is too harsh.', '{"1": "Expelling without inquiry is too harsh.", "2": "II does not follow.", "3": "Contacting the parents is a sensible step."}'),
  ('LR-0101', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Road accidents caused by drivers using hand-held mobile phones have increased.
Course of action I: Using a hand-held phone while driving should be banned and fined.
Course of action II: Mobile phones should be banned throughout the country.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'A targeted ban on phone use while driving addresses the problem. Banning all phones is extreme and unrelated to most phone use.', '{"1": "A nationwide ban on phones is extreme.", "2": "II does not follow.", "3": "I directly addresses the cause."}'),
  ('LR-0102', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Rumours that a vaccine causes infertility are spreading on social media and parents are refusing it.
Course of action I: Health authorities should run an awareness campaign with correct information.
Course of action II: The vaccination campaign should be stopped.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'False rumours are best countered with correct information. Stopping vaccination would harm children and reward the rumour.', '{"1": "Stopping vaccination would be harmful.", "2": "II does not follow.", "3": "I is a sensible step."}'),
  ('LR-0103', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A factory is discharging untreated waste into a river that people downstream use for drinking water.
Course of action I: Environmental authorities should take action against the factory.
Course of action II: People downstream should be warned and given safe drinking water.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Stopping the pollution and protecting people from it are both needed.', '{"0": "II is also needed to protect people now.", "1": "I is also needed to stop the cause.", "3": "Both are sensible."}'),
  ('LR-0104', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A newly built bridge has developed cracks within a month of opening.
Course of action I: An inquiry should be held into the quality of construction.
Course of action II: Engineers should inspect the bridge and close it if it is unsafe.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Checking safety protects the public now, and an inquiry finds who is responsible. Both follow.', '{"0": "II is also needed for public safety.", "1": "I is also needed to find the cause.", "3": "Both are sensible."}'),
  ('LR-0105', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A child fell into an open manhole on a busy street.
Course of action I: The child should be rescued and given medical treatment.
Course of action II: The authorities should cover the open manholes in the area.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Rescue deals with the emergency, and covering the manholes prevents it happening again.', '{"0": "II is also needed to prevent more accidents.", "1": "I is the most urgent step.", "3": "Both are sensible."}'),
  ('LR-0106', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A student found a wallet with an identity card in the college corridor.
Course of action I: The student should keep the money in the wallet.
Course of action II: The student should hand the wallet to the college office or contact the owner.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Returning the wallet is the honest and practical course. Keeping the money is wrong.', '{"0": "Keeping someone else''s money is wrong.", "2": "I does not follow.", "3": "II is the right course."}'),
  ('LR-0107', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Some workers at a construction site were injured because they were not wearing helmets.
Course of action I: All construction work in the country should be stopped.
Course of action II: The company should make safety gear compulsory and check that it is used.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Enforcing safety gear addresses the cause. Stopping all construction everywhere is extreme.', '{"0": "Stopping all construction is extreme.", "2": "I does not follow.", "3": "II addresses the cause."}'),
  ('LR-0108', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Cases of cheating were reported in a few examination halls.
Course of action I: The whole examination should be cancelled across the country without any inquiry.
Course of action II: The reported cases should be investigated and invigilation in those halls should be strengthened.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'A problem in a few halls calls for a targeted inquiry. Cancelling the exam for everyone, without inquiry, punishes honest students.', '{"0": "Cancelling without inquiry is extreme.", "2": "I does not follow.", "3": "II is a sensible step."}'),
  ('LR-0109', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: The water tank of a hostel was found to be contaminated.
Course of action I: Students should stop drinking water altogether.
Course of action II: The tank should be cleaned and the water tested before use.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Cleaning and testing make the water safe again. Stopping drinking water altogether is impossible and harmful.', '{"0": "People cannot stop drinking water.", "2": "I does not follow.", "3": "II is the sensible step."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0110', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: One of the 500 new chairs delivered to the college hall has a small scratch.
Course of action I: All 500 chairs should be returned.
Course of action II: The whole furniture order should be cancelled.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'A small scratch on one chair does not justify returning or cancelling everything; at most that one chair is replaced.', '{"0": "Returning all 500 chairs is out of proportion.", "1": "Cancelling the whole order is out of proportion.", "2": "Neither course follows."}'),
  ('LR-0111', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: It rained lightly for ten minutes in the city this morning.
Course of action I: All schools should be closed for a week.
Course of action II: A flood emergency should be declared in the city.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'Ten minutes of light rain does not call for either drastic step.', '{"0": "Closing schools for a week is out of proportion.", "1": "There is no sign of a flood.", "2": "Neither course follows."}'),
  ('LR-0112', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A batsman was out for zero runs in one match.
Course of action I: He should be banned from cricket for life.
Course of action II: His team should be disqualified from the tournament.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'One poor innings is normal in sport and does not justify either punishment.', '{"0": "A life ban is out of proportion.", "1": "The team has done nothing to be disqualified for.", "2": "Neither course follows."}'),
  ('LR-0113', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: One passenger on a flight complained that the meal was cold.
Course of action I: The airline should stop serving meals on all flights.
Course of action II: The pilot should be dismissed.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'A single complaint about food does not justify ending meal service, and the pilot is not responsible for meals.', '{"0": "Ending all meal service is out of proportion.", "1": "The pilot does not serve meals.", "2": "Neither course follows."}'),
  ('LR-0114', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: The number of candidates applying for MDCAT has increased sharply this year.
Course of action I: The testing body should arrange more test centres if needed.
Course of action II: The test should be cancelled this year.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'More candidates call for more capacity. Cancelling the test would harm every candidate.', '{"1": "Cancelling the test is unreasonable.", "2": "II does not follow.", "3": "I is a sensible step."}'),
  ('LR-0115', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Many elderly people find it difficult to stand in long queues at a bank.
Course of action I: The bank should set up a separate counter for senior citizens.
Course of action II: Senior citizens should be banned from visiting banks.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'A separate counter solves the problem; banning elderly customers is unfair and unreasonable.', '{"1": "Banning the elderly from banks is unfair.", "2": "II does not follow.", "3": "I is a sensible step."}'),
  ('LR-0116', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Heavy rain fell in the river''s catchment area for a week.
Statement II: The river overflowed its banks.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'A week of heavy rain raises the river until it floods, so I causes II.', '{"1": "A flood cannot cause the rain that came before it.", "2": "The rain itself is the cause.", "3": "Rain directly raises river levels."}'),
  ('LR-0117', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: The emergency ward of the city hospital was suddenly crowded.
Statement II: A bus overturned on the motorway near the city.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'The accident sent many injured people to hospital, so II causes I.', '{"0": "A crowded ward cannot cause a bus to overturn.", "2": "The accident directly explains the crowding.", "3": "The two are clearly linked."}'),
  ('LR-0118', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Prices of vegetables rose sharply in the markets.
Statement II: Floods destroyed crops across the province.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Destroyed crops reduce supply, which pushes prices up, so II causes I.', '{"0": "Higher prices do not destroy crops.", "2": "The floods directly explain the price rise.", "3": "Supply and price are linked."}'),
  ('LR-0119', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Sales of umbrellas rose in the city.
