INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0130', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: The college library bought new computers.
Statement II: A rare bird was spotted in the Margalla Hills.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 3, 'There is no causal connection between the two events.', '{"0": "Buying computers cannot bring a bird.", "1": "A bird sighting cannot cause a purchase.", "2": "Nothing suggests a shared cause."}'),
  ('LR-0131', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Electricity demand in the city reached a record high.
Statement II: Sales of cold drinks rose sharply.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Both are effects of a common cause: a heatwave, which makes people run fans and air conditioners and buy cold drinks.', '{"0": "Using more electricity does not make people buy cold drinks.", "1": "Buying cold drinks does not raise electricity demand on this scale.", "3": "They share a cause."}'),
  ('LR-0132', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', '"Every time I use my green pen, I do well in the test. So the pen causes good marks."
What is the flaw in this reasoning?', '["Pens cannot be green", "It treats something that happens together with success as its cause", "The student never does well", "It uses too many tests as evidence"]', 1, 'Using the pen and doing well happen together, but nothing shows the pen causes the marks; preparation does.', '{"0": "The colour of the pen is not the issue.", "2": "The student says they do well; the flaw is in explaining why.", "3": "The number of tests is not the problem."}'),
  ('LR-0133', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'A black cat crossed Bilal''s path, and later he missed his bus. He blames the cat.
Which is the best reason to reject his belief?', '["Cats are not allowed on roads", "Buses never run late", "There is no way the cat could have made him late; the two events only happened close together", "Bilal does not own a cat"]', 2, 'One event following another does not prove it caused it. Leaving late is a far more likely cause.', '{"0": "Where cats may go is irrelevant.", "1": "This is false and irrelevant.", "3": "Whose cat it was does not matter."}'),
  ('LR-0134', 'Logical Reasoning', 'Cause and effect', 'Common causes', 'hard', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'In a city, ice-cream sales and the number of drowning cases both rise in the same months.
What is the most likely explanation?', '["Eating ice cream causes drowning", "Drowning makes people buy ice cream", "The two numbers are not related at all", "Hot weather increases both ice-cream sales and swimming"]', 3, 'Both rise in hot months: people buy more ice cream and swim more, and more swimming leads to more drownings.', '{"0": "There is no mechanism by which ice cream causes drowning.", "1": "This reverses the link and makes no sense.", "2": "They are related, through a shared cause."}'),
  ('LR-0135', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'moderate', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'A gas cylinder exploded in a kitchen, and investigators found the gas valve was slightly open overnight.
What is the most reasonable explanation of the explosion?', '["Leaked gas built up and was ignited by a spark or flame", "The cylinder was painted the wrong colour", "The kitchen was too clean", "The explosion caused the valve to open"]', 0, 'An open valve lets gas build up; a spark or flame then ignites it. This explains the event with the evidence found.', '{"1": "Paint colour cannot cause an explosion.", "2": "Cleanliness does not cause gas explosions.", "3": "The valve was open overnight, before the explosion."}'),
  ('LR-0136', 'Logical Reasoning', 'Cause and effect', 'Positive reasoning', 'easy', 'Examwise original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.3', 'A student failed MDCAT on the first attempt. Which response shows the most constructive reasoning?', '["\"I am simply not intelligent enough to be a doctor.\"", "\"I will find out which sections went wrong and make a study plan for the next attempt.\"", "\"Luck decides results, so effort makes no difference.\"", "\"The test was unfair only to me, so preparing again is pointless.\""]', 1, 'Looking for the real causes of the result and acting on them is positive, evidence-based thinking.', '{"0": "One result does not prove a fixed lack of ability.", "2": "Preparation clearly affects scores; this is a false belief.", "3": "Blaming the test without evidence stops the student from improving."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

