-- English in the AKU bank (every question) and the NUMS bank (all but the literary ones), under the same chapter.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'aku', q.id, 'English', q.chapter FROM questions q
WHERE q.id BETWEEN 'ENG-0010' AND 'ENG-0295' AND q.source LIKE 'Examwise original question.%';
